/**
 * The TS port of the brain's resolve_incompatible_pair, checked against vectors generated by
 * running the brain's real function (scripts/gen-resolver-vectors.py). A case failing here means
 * the port disagrees with what the hosted product runs.
 */
import { describe, expect, it } from 'vitest';
import vectors from '../resolver-vectors.json' with { type: 'json' };
import { CONCURRENT_WINDOW_HOURS, type PairSide, parseDecidedAt, resolveIncompatiblePair } from '../resolve-pair.js';

type VectorSide = (typeof vectors.cases)[number]['a'];
const toSide = (s: VectorSide): PairSide => ({
  id: s.id,
  decidedAt: s.decided_at,
  author: s.author,
  status: s.status,
  standing: s.standing,
  exceptedBy: s.excepted_by,
});

describe('resolveIncompatiblePair matches the brain', () => {
  it('positive control: vectors loaded and the window matches', () => {
    expect(vectors.cases.length).toBeGreaterThan(10);
    expect(vectors.concurrentWindowHours).toBe(CONCURRENT_WINDOW_HOURS);
  });

  it.each(vectors.cases)('$name', (c) => {
    expect(resolveIncompatiblePair(toSide(c.a), toSide(c.b), c.replacedBy)).toEqual(c.expected);
  });
});

describe('parseDecidedAt', () => {
  it('reads a naive time as UTC, not as the machine local zone', () => {
    expect(parseDecidedAt('2026-01-01T10:00:00')?.toISOString()).toBe('2026-01-01T10:00:00.000Z');
    expect(parseDecidedAt('2026-01-01 10:00:00')?.toISOString()).toBe('2026-01-01T10:00:00.000Z');
  });

  it('reads an offset as an instant', () => {
    expect(parseDecidedAt('2026-01-01T10:00:00+02:00')?.toISOString()).toBe('2026-01-01T08:00:00.000Z');
    expect(parseDecidedAt('2026-01-01T10:00:00Z')?.toISOString()).toBe('2026-01-01T10:00:00.000Z');
  });

  it('treats garbage and non-strings as missing', () => {
    expect(parseDecidedAt('yesterday')).toBeNull();
    expect(parseDecidedAt('2026-13-45')).toBeNull();
    expect(parseDecidedAt(null)).toBeNull();
    expect(parseDecidedAt(42)).toBeNull();
  });
});
